def largest_subset(nums):
    from collections import defaultdict

    if not nums:
        return 0  # Edge case: empty list

    # Helper function to compute prime factors of a number
    def prime_factors(n):
        factors = set()
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors.add(d)
                n //= d
            d += 1
        if n > 1:
            factors.add(n)
        return factors

    # Map of prime factors to the count of numbers divisible by them
    factor_count = defaultdict(int)

    for num in nums:
        factors = prime_factors(num)
        for factor in factors:
            factor_count[factor] += 1

    # The largest subset size will be the maximum count among all factors
    return max(factor_count.values(), default=0)
